/* Calendrier pédagogique France 2026. Données et références restent éditables. */
(()=>{'use strict';
const VIS='https://professionnels.vaccination-info-service.fr/';
const sources={calendar:['Santé publique France · calendrier 2026 (septembre)','https://www.santepubliquefrance.fr/sites/default/files/cadic_files/documents/spf00006840.pdf'],hpv:['Vaccination Info Service · HPV',VIS+'Maladies-et-leurs-vaccins/Infections-a-papillomavirus-humain-HPV'],pertussis:['Vaccination Info Service · coqueluche',VIS+'Maladies-et-leurs-vaccins/Coqueluche'],pneumo:['Vaccination Info Service · pneumocoques',VIS+'Maladies-et-leurs-vaccins/Infections-a-pneumocoques'],pregnancy:['Vaccination Info Service · grossesse',VIS+'Recommandations-vaccinales-specifiques/Personnes-exposees-a-des-risques-specifiques/Femmes-enceintes'],immuno:['Vaccination Info Service · immunodépression',VIS+'Recommandations-vaccinales-specifiques/Patient-immunodeprime/Principes-generaux'],spleen:['Vaccination Info Service · asplénie',VIS+'Recommandations-vaccinales-specifiques/Patient-immunodeprime/Patient-asplenique-ou-hyposplenique'],preterm:['Vaccination Info Service · prématurité',VIS+'Recommandations-vaccinales-specifiques/Personnes-exposees-a-des-risques-specifiques/Prematures'],staff:['Vaccination Info Service · professionnels de santé',VIS+'Recommandations-vaccinales-specifiques/Professionnels-exposes-a-des-risques-specifiques/Professionnels-de-sante']};
const vaccines={
 hexa:{name:'DTCaP · Hib · VHB',sub:'Hexavalent',tone:'blue',when:'2, 4 et 11 mois',text:'Le vaccin combiné protège contre diphtérie, tétanos, coqueluche, poliomyélite, Haemophilus influenzae b et hépatite B.',note:'Obligatoire chez le nourrisson. Distinguer les rappels DTCaP ultérieurs du schéma Hib–VHB.',ref:'calendar'},
 pneumo:{name:'Pneumocoque',sub:'VPC13 ou VPC15',tone:'green',when:'2, 4 et 11 mois',text:'Schéma usuel du nourrisson né à terme avec les vaccins conjugués 13 ou 15 valences. Chez le prématuré et le nourrisson à risque : 2, 3, 4 et 11 mois.',note:'Obligatoire chez le nourrisson. Le schéma dépend du produit et du terrain ; ne pas transposer ces trois doses à tout vaccin pneumococcique.',ref:'pneumo'},
 menb:{name:'Méningocoque B',sub:'MenB',tone:'rose',when:'3, 5 et 12 mois',text:'Primovaccination à 3 et 5 mois, puis rappel à 12 mois. Le rattrapage avant 5 ans dépend de l’âge de début et du vaccin.',note:'Obligation chez le nourrisson et rattrapage des enfants nés depuis le 1er janvier 2023. À 15–24 ans, vaccination possible selon la situation.',ref:'calendar'},
 acwy:{name:'Méningocoques ACWY',sub:'MenACWY',tone:'purple',when:'6 et 12 mois, puis 11–14 ans',text:'Chez le nourrisson : une dose à 6 mois et une à 12 mois. À l’adolescence : une dose à 11–14 ans, même après vaccination antérieure ; rattrapage à 15–24 ans.',note:'Obligatoire chez le nourrisson. Rattrapage des enfants nés depuis le 1er janvier 2023 avant 5 ans. Utiliser un vaccin autorisé pour l’âge.',ref:'calendar'},
 ror:{name:'Rougeole · oreillons · rubéole',sub:'ROR',tone:'amber',when:'12 puis 16–18 mois',text:'Deux doses pour tous les enfants. Chez les personnes nées depuis 1980, vérifier deux doses au total, à au moins un mois d’intervalle.',note:'Vaccin vivant : contre-indiqué pendant la grossesse. Une dose administrée avant 12 mois ne remplace pas les deux doses du calendrier.',ref:'calendar'},
 rota:{name:'Rotavirus',sub:'Voie orale',tone:'teal',when:'2 et 3 mois, ± 4 mois',text:'Deux doses avec Rotarix, trois avec RotaTeq. La dose du quatrième mois dépend donc du vaccin utilisé.',note:'Recommandé. Respecter les limites d’âge propres au produit ; pas de rattrapage tardif libre. Informer sur les signes d’invagination intestinale.',ref:'calendar'},
 bcg:{name:'Tuberculose',sub:'BCG si risque',tone:'slate',when:'Dès 1 mois si risque élevé',text:'Vaccination ciblée des enfants exposés à un risque élevé de tuberculose, avec possibilité de rattrapage jusqu’à 15 ans selon indication.',note:'Pas de vaccination universelle. Des modalités plus précoces s’appliquent notamment en Guyane et à Mayotte. Vaccin vivant.',ref:'calendar'},
 dtp:{name:'Diphtérie · tétanos · polio · coqueluche',sub:'Rappels combinés',tone:'blue',when:'6 ans, 11–13 ans, 25, 45, 65 ans, puis tous les 10 ans',text:'DTCaP à 6 ans, dTcaP à 11–13 ans. En 2026, les rappels de l’adulte comportent systématiquement la coqueluche avec le dTcaP, en raison de l’indisponibilité du dTP seul.',note:'La grossesse et certaines expositions professionnelles peuvent justifier un rappel sans attendre ces âges fixes.',ref:'pertussis'},
 hpv:{name:'Papillomavirus',sub:'HPV',tone:'purple',when:'11–14 ans ; rattrapage jusqu’à 26 ans inclus',text:'Filles et garçons : deux doses si début entre 11 et 14 ans (intervalle 5–13 mois). Si début entre 15 et 26 ans : trois doses à M0, M2 et M6.',note:'Gardasil 9 pour une nouvelle vaccination. Une vaccination commencée n’est pas à recommencer en cas de retard. Le dépistage du col reste nécessaire.',ref:'hpv'},
 pneumoAdult:{name:'Pneumocoque',sub:'VPC20 ou VPC21',tone:'green',when:'Dès 65 ans ; dès 18 ans si risque',text:'Chez l’adulte non vacciné concerné : une dose de vaccin conjugué 20 ou 21 valences. Les vaccinations antérieures modifient le délai et la séquence à suivre.',note:'L’indication à partir de 65 ans ne dépend plus de la présence d’une comorbidité.',ref:'pneumo'},
 zona:{name:'Zona',sub:'Vaccin recombinant',tone:'rose',when:'Dès 65 ans ; dès 18 ans si immunodépression',text:'Schéma à deux doses, habituellement séparées de deux mois. L’intervalle peut être adapté dans certaines situations d’immunodépression.',note:'Il s’agit d’un vaccin non vivant. Vérifier le schéma antérieur et les recommandations propres au terrain.',ref:'calendar'},
 flu:{name:'Grippe',sub:'Chaque année',tone:'amber',when:'Dès 65 ans ; plus tôt selon le terrain',text:'Vaccination annuelle recommandée à partir de 65 ans, pendant la grossesse et chez les personnes à risque de forme grave. Elle peut aussi être proposée aux enfants de 2 à 17 ans sans comorbidité.',note:'Grossesse : à tout trimestre. Les maladies chroniques, l’obésité sévère et certaines expositions professionnelles sont aussi à prendre en compte.',ref:'calendar'},
 covid:{name:'Covid-19',sub:'Campagnes saisonnières',tone:'teal',when:'Campagne d’automne ; renouvellement ciblé au printemps',text:'Cible principale : personnes de 65 ans et plus et personnes à risque, notamment immunodéprimées ou enceintes. La campagne printanière concerne notamment les 80 ans et plus, EHPAD/USLD et personnes immunodéprimées.',note:'Le nombre de doses dépend des campagnes et du terrain ; ce n’est pas un rappel fixe à chaque anniversaire indiqué dans la grille.',ref:'calendar'},
 vrs:{name:'VRS',sub:'Protection respiratoire',tone:'slate',when:'Dès 75 ans ; dès 65 ans si maladie cardiorespiratoire chronique',text:'Vaccination recommandée aux personnes de 75 ans et plus et, dès 65 ans, si une maladie respiratoire ou cardiaque chronique expose à une décompensation.',note:'Pendant la grossesse, la vaccination maternelle à 32–36 SA en période saisonnière est une autre indication, destinée à protéger le nourrisson.',ref:'calendar'}
};
const groups={
 baby:{label:'Nourrisson',range:'1 à 18 mois',ages:['1 mois','2 mois','3 mois','4 mois','5 mois','6 mois','11 mois','12 mois','16–18 mois'],rows:[['hexa',[null,'1',null,'2',null,null,'R',null,null]],['pneumo',[null,'1',null,'2',null,null,'R',null,null]],['menb',[null,null,'1',null,'2',null,null,'R',null]],['acwy',[null,null,null,null,null,'1',null,'2',null]],['ror',[null,null,null,null,null,null,null,'1','2']],['rota',[null,'1','2','± 3',null,null,null,null,null]],['bcg',['Risque',null,null,null,null,null,null,null,null]]],note:'Repères du nourrisson né à terme. R = rappel ; ± = selon le vaccin. Le BCG dépend du risque.'},
 young:{label:'Enfant & adolescent',range:'6 à 26 ans',ages:['6 ans','11–13 ans','14 ans','15–24 ans','25–26 ans'],rows:[['dtp',['R','R',null,null,'25 ans']],['hpv',[null,'2 doses','2 doses','3 doses','3 doses']],['acwy',[null,'1 dose','1 dose','Rattrapage',null]],['menb',[null,null,null,'Possible',null]],['ror',['Vérifier','Vérifier','Vérifier','Vérifier','Vérifier']]],note:'Les cases d’une même tranche décrivent une fenêtre vaccinale, pas une dose à chaque âge. HPV et ACWY : distinguer vaccination initiale et rattrapage.'},
 adult:{label:'Adulte & senior',range:'25 ans et plus',ages:['25 ans','45 ans','65 ans','75 ans','85 ans et +'],rows:[['dtp',['R','R','R','R','10 ans']],['pneumoAdult',[null,null,'1 dose','Si à faire','Si à faire']],['zona',[null,null,'2 doses','Si à faire','Si à faire']],['flu',[null,null,'Annuel','Annuel','Annuel']],['covid',[null,null,'Campagne','Campagne','Campagne']],['vrs',[null,null,'Si risque','1 dose','Si à faire']]],note:'Les cases « si à faire » ne sont pas des rappels supplémentaires. Les terrains à risque peuvent avancer les indications, parfois dès 18 ans.'}
};
const terrains=[
 {id:'pregnancy',name:'Grossesse',sub:'Protéger la mère et le nourrisson',tone:'rose',lead:'Une vaccination coqueluche à chaque grossesse.',points:[['Coqueluche','Dès le deuxième trimestre, de préférence entre 20 et 36 SA, même si une vaccination a eu lieu avant la grossesse.'],['Grippe & Covid-19','Selon les campagnes, à tout trimestre.'],['VRS','Entre 32 et 36 SA en période saisonnière (septembre à janvier) ; articuler avec la prévention du VRS chez le nouveau-né.'],['Vaccins vivants','ROR et varicelle sont contre-indiqués pendant la grossesse ; anticiper avant ou programmer après.']],ref:'pregnancy'},
 {id:'immuno',name:'Immunodépression',sub:'Adapter le schéma au déficit',tone:'purple',lead:'Anticiper avant le traitement quand c’est possible.',points:[['Vaccins non vivants','Utilisables ; la réponse peut être diminuée et les schémas renforcés selon le terrain.'],['Vaccins vivants','Contre-indiqués en principe. Les exceptions relèvent d’une évaluation spécialisée, pas du seul chiffre de CD4.'],['Protection renforcée','Vérifier pneumocoque, grippe, Covid-19 et zona recombinant selon âge et indication ; compléter le calendrier courant.'],['Entourage','Vérifier aussi sa vaccination pour réduire l’exposition.']],ref:'immuno'},
 {id:'spleen',name:'Asplénie',sub:'Penser aux bactéries encapsulées',tone:'green',lead:'Pneumocoque, méningocoques et Hib.',points:[['Priorités','Vérifier pneumocoque, méningocoques ACWY et B, et Haemophilus influenzae b.'],['Schémas','Adapter les doses et rappels à l’âge, aux produits et à l’historique vaccinal.'],['Splénectomie programmée','Anticiper les vaccinations avant l’intervention lorsque c’est possible.'],['Chaque année','Vacciner contre la grippe ; la vaccination ne remplace pas l’éducation et la conduite urgente devant une fièvre.']],ref:'spleen'},
 {id:'preterm',name:'Prématurité',sub:'Se repérer sur l’âge chronologique',tone:'blue',lead:'Commencer à 2 mois d’âge chronologique.',points:[['Même âge de départ','Ne pas attendre l’âge corrigé ; utiliser les mêmes doses vaccinales.'],['Pneumocoque','Avec VPC13 ou VPC15 : schéma renforcé à 2, 3, 4 et 11 mois.'],['Hépatite B','Tenir compte du statut maternel, du terme et du poids de naissance pour la prophylaxie néonatale.'],['Surveillance','Les plus fragiles peuvent nécessiter une surveillance cardiorespiratoire après vaccination.']],ref:'preterm'},
 {id:'staff',name:'Soignants',sub:'Protéger aussi les patients',tone:'teal',lead:'Vérifier l’immunisation selon le poste et l’exposition.',points:[['Hépatite B','Documenter vaccination et protection dans les professions soumises à l’obligation.'],['Coqueluche','Vigilance particulière au contact de nourrissons ; appliquer les recommandations de rappel liées à l’exposition.'],['Grippe & Covid-19','Suivre les recommandations et campagnes applicables aux professionnels de santé.'],['Rougeole & varicelle','Vérifier les antécédents et proposer un rattrapage selon les recommandations et les contre-indications.']],ref:'staff'}
];
let state={mode:'calendar',group:'baby',mask:'vaccines',revealed:new Set(),terrain:'pregnancy'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=key=>{const s=sources[key];return `<a href="${s[1]}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a>`};
const button=(label,action,value,extra='')=>`<button type="button" data-vax="${action}" data-value="${value}" ${extra}>${label}</button>`;
function masked(label,key){const shown=state.revealed.has(key);return button(shown?esc(label):'•••','reveal',key,`class="vax-mask ${shown?'revealed':''}" aria-label="${shown?esc(label):'Révéler '+(key.startsWith('age')?'l’âge':'le vaccin')+' '+(Number(key.split('-')[1])+1)}" aria-pressed="${shown}"`)}
function table(){const g=groups[state.group],quiz=state.mode==='recall';return `<div class="vax-table-scroll" tabindex="0" role="region" aria-label="Calendrier ${g.label}, défilement horizontal"><table class="vax-table"><caption class="vax-sr">Calendrier vaccinal : ${g.label}. Cliquer sur une pastille pour les précisions.</caption><thead><tr><th scope="col">Vaccin</th>${g.ages.map((a,i)=>`<th scope="col">${quiz&&state.mask==='ages'?masked(a,'age-'+i):esc(a)}</th>`).join('')}</tr></thead><tbody>${g.rows.map(([key,values],i)=>{const v=vaccines[key];return `<tr class="vax-tone-${v.tone}"><th scope="row">${quiz&&state.mask==='vaccines'?masked(v.name,'vac-'+i):button(`<strong>${esc(v.name)}</strong><small>${esc(v.sub)}</small>`,'detail',key,'class="vax-row-label"')}</th>${values.map((value,j)=>`<td>${value?button(esc(value),'detail',key,`class="vax-dose" aria-label="${quiz?'Voir le détail de la ligne '+(i+1):esc(v.name)}${quiz&&state.mask==='ages'?'':', '+esc(g.ages[j])} : ${esc(value)}"`):'<span class="vax-empty" aria-hidden="true">·</span>'}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><p class="vax-footnote">${esc(g.note)}</p>`}
function terrain(){const t=terrains.find(t=>t.id===state.terrain);return `<div class="vax-terrain-layout"><div class="vax-terrain-menu" role="group" aria-label="Choisir un terrain">${terrains.map(t=>button(`<strong>${t.name}</strong><small>${t.sub}</small>`,'terrain',t.id,`aria-pressed="${t.id===state.terrain}"`)).join('')}</div><article class="vax-terrain vax-tone-${t.tone}"><div class="vax-terrain-intro"><p>${t.name}</p><h3>${t.lead}</h3></div><dl>${t.points.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><div class="vax-source">${link(t.ref)}</div></article></div>`}
function panel(){if(state.mode==='terrain')return terrain();return `<div class="vax-age-tabs" role="group" aria-label="Tranche d’âge">${Object.entries(groups).map(([key,g])=>button(`<strong>${g.label}</strong><small>${g.range}</small>`,'group',key,`aria-pressed="${key===state.group}"`)).join('')}</div>${state.mode==='recall'?`<div class="vax-recall-tools"><p>Retrouve les repères, puis touche une case masquée pour vérifier.</p><div><label>Masquer <select aria-label="Éléments à masquer" data-vax-mask><option value="vaccines" ${state.mask==='vaccines'?'selected':''}>les vaccins</option><option value="ages" ${state.mask==='ages'?'selected':''}>les âges</option></select></label>${button('Tout révéler','all','', 'class="vax-text-button"')}${button('Remasquer','reset','', 'class="vax-text-button"')}</div><span class="vax-recall-status" role="status">${state.revealed.size} repère${state.revealed.size===1?'':'s'} révélé${state.revealed.size===1?'':'s'}</span></div>`:`<div class="vax-calendar-help"><p>Lis par âge. Touche une pastille pour ouvrir le détail.</p><span>France · 2026</span></div>`}${table()}`}
function render(){return `<section class="vax-root" aria-label="Calendrier vaccinal interactif"><header class="vax-hero"><img src="atlas-medical/editorial/vaccination-vie.png" alt="" width="1344" height="752"><div><p>Les rendez-vous qui protègent</p><h2>La vaccination,<br>au fil de la vie.</h2><span>Comprendre les dates.<br>Retenir les bons repères.</span></div></header><nav class="vax-modes" aria-label="Modes du calendrier">${[['calendar','Calendrier'],['recall','Tableau à trous'],['terrain','Selon le terrain']].map(([k,v])=>button(v,'mode',k,`aria-pressed="${state.mode===k}"`)).join('')}</nav><div class="vax-panel">${panel()}</div><footer class="vax-references"><p>Repères de révision du calendrier français 2026, vérifiés le 16 octobre 2026. Les rattrapages se construisent à partir des doses déjà reçues et du terrain.</p>${link('calendar')}<a href="#item/146">Revenir aux objectifs de cours</a></footer></section>`}
function refresh(focus){const root=document.querySelector('.vax-root');if(!root)return;root.querySelector('.vax-panel').innerHTML=panel();root.querySelectorAll('[data-vax="mode"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===state.mode)));if(focus)root.querySelector(focus)?.focus({preventScroll:true})}
function detail(key,opener){const v=vaccines[key];if(!v)return;document.querySelector('.vax-dialog')?.remove();const d=document.createElement('dialog');d.className='vax-dialog vax-tone-'+v.tone;d.setAttribute('aria-labelledby','vax-dialog-title');d.innerHTML=`<div class="vax-dialog-heading"><span>Calendrier 2026</span><button type="button" class="vax-close" aria-label="Fermer le détail">×</button></div><h2 id="vax-dialog-title">${esc(v.name)}</h2><p class="vax-when">${esc(v.when)}</p><p>${esc(v.text)}</p><div class="vax-remember"><strong>À retenir</strong><p>${esc(v.note)}</p></div><div class="vax-source">${link(v.ref)}</div>`;document.body.append(d);d.querySelector('.vax-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{d.remove();if(opener.isConnected)opener.focus({preventScroll:true})},{once:true});d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-vax]');if(!b)return;const {vax:action,value}=b.dataset;if(action==='detail'){detail(value,b);return}if(action==='mode')state.mode=value;if(action==='group'){state.group=value;state.revealed.clear()}if(action==='terrain')state.terrain=value;if(action==='reveal')state.revealed.has(value)?state.revealed.delete(value):state.revealed.add(value);if(action==='reset')state.revealed.clear();if(action==='all'){const g=groups[state.group],count=state.mask==='ages'?g.ages.length:g.rows.length;state.revealed=new Set(Array.from({length:count},(_,i)=>(state.mask==='ages'?'age-':'vac-')+i))}refresh(`[data-vax="${action}"][data-value="${value}"]`)});
document.addEventListener('change',e=>{if(!e.target.matches('[data-vax-mask]'))return;state.mask=e.target.value;state.revealed.clear();refresh('[data-vax-mask]')});
window.addEventListener('hashchange',()=>document.querySelector('.vax-dialog')?.close());
window.ATLAS_VACCINES={render,teaser:()=>'<a class="vax-teaser" href="#item/146/vaccins"><span><strong>Le calendrier vaccinal, en un regard.</strong><small>Par âge, à trous ou selon le terrain</small></span><span aria-hidden="true">↗</span></a>'};
})();
